// Every source module has a colocated test (site/AGENTS.md): src/foo.tsx → src/foo.test.tsx. Exempt:
// the Astro pages and layouts (entry points, checked by `astro check` and the build), the test harness, and components/ui/ (generated by the shadcn CLI and covered by
// components/ui/primitives.test.tsx).
import { existsSync, readdirSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'

const ROOT = new URL('../src', import.meta.url).pathname
const EXEMPT = [/^test\//, /^components\/ui\//, /\.d\.ts$/]

const missing = []
const walk = (dir) => {
  for (const name of readdirSync(dir)) {
    const path = join(dir, name)
    if (statSync(path).isDirectory()) walk(path)
    else if (/\.tsx?$/.test(name) && !/\.test\.tsx?$/.test(name)) {
      const rel = relative(ROOT, path)
      if (EXEMPT.some((re) => re.test(rel))) continue
      const base = path.replace(/\.tsx?$/, '')
      if (!existsSync(`${base}.test.ts`) && !existsSync(`${base}.test.tsx`)) missing.push(`src/${rel}`)
    }
  }
}
walk(ROOT)
if (missing.length) {
  console.error(`No colocated test for:\n${missing.map((m) => `  ${m}`).join('\n')}`)
  process.exit(1)
}
